using CatalogService.Models;using CatalogService.Services;namespace CatalogService.Endpoints;public static class CatalogEndpoints{public static void MapCatalogEndpoints(this WebApplication app){app.MapGet("/health",()=>Results.Ok(new{service="catalog",status="healthy"}));app.MapGet("/api/catalog/subjects",(SubjectStore s)=>Results.Ok(s.GetAll()));app.MapGet("/api/catalog/subjects/{id:int}",(int id,SubjectStore s)=>{var x=s.Get(id);return x is null?Results.NotFound():Results.Ok(x);});app.MapPost("/api/catalog/subjects",(CreateSubjectRequest r,SubjectStore s)=>{if(string.IsNullOrWhiteSpace(r.Code)||string.IsNullOrWhiteSpace(r.Name))return Results.BadRequest(new{error="Code and name are required."});var x=s.Add(r);return Results.Created($"/api/catalog/subjects/{x.Id}",x);});app.MapPut("/api/catalog/subjects/{id:int}",(int id,UpdateSubjectRequest r,SubjectStore s)=>{var x=s.Update(id,r);return x is null?Results.NotFound():Results.Ok(x);});app.MapDelete("/api/catalog/subjects/{id:int}",(int id,SubjectStore s)=>s.Delete(id)?Results.NoContent():Results.NotFound());}}